From f31e29f7197a7570749a6d5df1c6acb9ca209885 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:40:23 +0100
Subject: [PATCH] shell/panelview: open tray entry settings on top of the tray
 settings

Opening an entry's settings from the System Tray settings replaced that
window, so changes not yet applied were lost. Settings of an applet
inside the applet being configured now open in their own window on top.

BUG: 484710
---
 shell/panelview.cpp | 31 ++++++++++++++++++++++---------
 shell/panelview.h   |  1 +
 2 files changed, 23 insertions(+), 9 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..762a5bf235 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -928,17 +928,30 @@ void PanelView::showConfigurationInterface(Plasma::Applet *applet)
         }
     } else {
         containment()->corona()->setEditMode(false);
-        if (m_appletConfigView && m_appletConfigView->applet() == applet) {
-            m_appletConfigView->show();
-            m_appletConfigView->requestActivate();
+        bool nested = false;
+        if (m_appletConfigView && m_appletConfigView->applet() != applet) {
+            for (QObject *parent = applet->parent(); parent && !nested; parent = parent->parent()) {
+                nested = parent == m_appletConfigView->applet();
+            }
+        }
+        QPointer<PlasmaQuick::ConfigView> &configView = nested ? m_nestedAppletConfigView : m_appletConfigView;
+        if (configView && configView->applet() == applet) {
+            configView->show();
+            configView->requestActivate();
             return;
-        } else if (m_appletConfigView) {
-            m_appletConfigView->deleteLater(); // BUG 476968
+        } else if (configView) {
+            configView->deleteLater(); // BUG 476968
+        }
+        if (!nested && m_nestedAppletConfigView) {
+            m_nestedAppletConfigView->deleteLater();
+        }
+        configView = new PlasmaQuick::ConfigView(applet);
+        configView->init();
+        if (nested) {
+            configView->setTransientParent(m_appletConfigView);
         }
-        m_appletConfigView = new PlasmaQuick::ConfigView(applet);
-        m_appletConfigView->init();
-        m_appletConfigView->show();
-        m_appletConfigView->requestActivate();
+        configView->show();
+        configView->requestActivate();
     }
 }

diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..df3b2f0283 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -352,6 +352,7 @@ private:
     bool m_touchingWindow = false;
     Qt::Alignment m_alignment;
     QPointer<PlasmaQuick::ConfigView> m_appletConfigView;
+    QPointer<PlasmaQuick::ConfigView> m_nestedAppletConfigView;
     QPointer<PlasmaQuick::PopupPlasmaWindow> m_panelConfigView;
     ShellCorona *m_corona;
     QTimer m_strutsTimer;
